-- Run in Supabase SQL Editor. RLS is the tenant isolation boundary.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null,role text not null default 'company_user' check(role in ('super_admin','company_admin','company_user')),can_edit_statutory boolean not null default false,created_at timestamptz default now());
create table if not exists public.companies(id uuid primary key default gen_random_uuid(),name text not null,establishment_code text,is_active boolean not null default true,created_at timestamptz default now());
create table if not exists public.company_memberships(id uuid primary key default gen_random_uuid(),company_id uuid references companies(id) on delete cascade,user_id uuid references profiles(id) on delete cascade,is_active boolean default true,unique(company_id,user_id));
create table if not exists public.statutory_settings(company_id uuid primary key references companies(id) on delete cascade,employee_pf_rate numeric default 12,employer_pf_rate numeric default 12,eps_rate numeric default 8.33,non_pension_cpf_rate numeric default 3.67,eps_wage_ceiling numeric default 15000,edli_rate numeric default .5,edli_wage_cap numeric default 15000,admin_charge_rate numeric default .5,updated_at timestamptz default now(),updated_by uuid references profiles(id));
create table if not exists public.employees(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,employee_code text not null,uan text not null check(uan ~ '^[0-9]{12}$'),employee_name text not null,date_of_joining date,date_of_exit date,pension_member boolean default true,epf_eligible boolean default true,status text default 'Active',remarks text,created_at timestamptz default now(),unique(company_id,employee_code),unique(company_id,uan));
create table if not exists public.wage_records(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,employee_id uuid not null references employees(id) on delete cascade,wage_month text not null check(wage_month ~ '^20[0-9]{2}-(0[1-9]|1[0-2])$'),pf_wages numeric not null default 0 check(pf_wages>=0),pension_wages numeric not null default 0 check(pension_wages>=0),days_worked integer default 0,ncp_days integer default 0,refund_of_advances numeric default 0,employee_pf integer default 0,employer_eps integer default 0,employer_epf integer default 0,edli integer default 0,admin_charge integer default 0,created_at timestamptz default now(),unique(company_id,employee_id,wage_month));
create table if not exists public.ecr_batches(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,wage_month text not null,employee_count integer default 0,status text default 'generated',file_name text,filing_date date,trrn text,challan_number text,payment_date date,payment_status text,created_at timestamptz default now(),unique(company_id,wage_month));
create table if not exists public.audit_logs(id bigint generated always as identity primary key,company_id uuid references companies(id) on delete set null,actor_id uuid references profiles(id),action text not null,table_name text not null,record_id text,details jsonb default '{}'::jsonb,created_at timestamptz default now());
create or replace function public.is_super_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='super_admin')$$;
create or replace function public.has_company_access(cid uuid) returns boolean language sql stable security definer set search_path=public as $$select public.is_super_admin() or exists(select 1 from company_memberships m join companies c on c.id=m.company_id where m.user_id=auth.uid() and m.company_id=cid and m.is_active and c.is_active)$$;
create or replace function public.can_edit_company_settings(cid uuid) returns boolean language sql stable security definer set search_path=public as $$select public.is_super_admin() or exists(select 1 from profiles p join company_memberships m on m.user_id=p.id where p.id=auth.uid() and m.company_id=cid and m.is_active and (p.role='company_admin' or p.can_edit_statutory))$$;
alter table profiles enable row level security; alter table companies enable row level security; alter table company_memberships enable row level security; alter table statutory_settings enable row level security; alter table employees enable row level security; alter table wage_records enable row level security; alter table ecr_batches enable row level security; alter table audit_logs enable row level security;
create policy "profile self or super" on profiles for select using(id=auth.uid() or is_super_admin());
create policy "company own or super" on companies for select using(is_super_admin() or has_company_access(id));
create policy "membership self or super" on company_memberships for select using(user_id=auth.uid() or is_super_admin());
create policy "settings read own" on statutory_settings for select using(has_company_access(company_id));
create policy "settings edit option B" on statutory_settings for update using(can_edit_company_settings(company_id)) with check(can_edit_company_settings(company_id));
create policy "employees tenant boundary" on employees for all using(has_company_access(company_id)) with check(has_company_access(company_id));
create policy "wages tenant boundary" on wage_records for all using(has_company_access(company_id)) with check(has_company_access(company_id));
create policy "batches tenant boundary" on ecr_batches for all using(has_company_access(company_id)) with check(has_company_access(company_id));
create policy "audit read tenant" on audit_logs for select using(is_super_admin() or (company_id is not null and has_company_access(company_id)));
create policy "audit insert tenant" on audit_logs for insert with check(actor_id=auth.uid() and (is_super_admin() or has_company_access(company_id)));
-- Deliberately no client insert policy on companies/profiles/memberships: provisioning is server-side only.
-- Bootstrap first super admin using supabase/bootstrap-super-admin.sql.
